mapper.select:
select id, mch_name as name, mch_short_name as shortName, contact_name as contactName, contact_tel as contactTel, contact_email as contactEmail, state, remark, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, create_time as createByName, update_by_name as updateByName, isv_id as isvId, `type` from pay_mch_info
and id = #{mchPage.mchId}
and `name` = #{mchPage.name}
and isv_id = #{mchPage.isvId}
and `type` = #{mchPage.type}
